</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>

using namespace std;

#define PI 3.1415926535897932384626433832795028841971693992

#define pb push_back
#define mp make_pair 
#define fi first
#define se second
#define ZERO(a) memset(a, 0, sizeof(a))
#define INIT(a) memset(a, 0xff, sizeof(a))
#define FOR(i, n) for (i=0; i<n; i++)
#define FORD(i, n) for (i=n-1; i>=0; i--)
#define FOR2(i, a, b) for (i=a; i<b; i++)
#define FOR2D(i, a, b) for (i=b-1; i>=a; i--)
#define BIT(i, m) (m&(1LL<<(i)))
#define RBIT(i, m) (m&~(1LL<<(i)))
#define ABIT(i, m) (m|(1LL<<(i)))
#define FORB(i, m) for (i=0; i<32; i++) if (BIT(i, m)>0)
#define ALL(a) a.begin(), a.end()
#define OUT(i, n) (i<0 || i>=n)
#define AT(a, i) (a[(i+a.size())%a.size()])
#define IT(v, i) (v.begin()+(i+v.size())%v.size())
#define IT2(v, i, j) IT(v, i), IT(v, j)
#define INSET(a, S) (S.find(a)!=S.end())

typedef vector<int> vi;
typedef long long ll;
typedef vector<ll> vll;
typedef pair<int, int> ii;
typedef vector<ii> vii;
typedef vector<string> vs;
typedef list<int> li;
typedef long double ld;

const int mod =1000000007;

ll pow(ll a, ll p)
{
  ll res = 1;
  while(p>0) {
    if (p%2==1) res *= a, res %= mod;
    a *= a, a %= mod, p/=2;
  }
  return res;
}

int main() 
{
    ll p,k;
    cin>>p>>k;
    if (k==0) {
        cout<<pow(p,p-1)<<endl;
        return 0;
    }
    if (k==1) {
        cout<<pow(p,p)<<endl;
        return 0;
    }
    ll order=1,a=k;
    while(a!=1) a*=k,a%=p,order++;
    cout<< pow(p,(p-1)/order) <<endl;
    return 0;
}


</original_code>
